using System.Text;

namespace AutoFluentValidation.SourceGenerator;

internal static class SourceEmitter {
	private static readonly string Version =
		typeof(SourceEmitter).Assembly.GetName().Version?.ToString(3) ?? "0.0.0";

	private static readonly string GeneratedCodeAttribute =
		"[global::System.CodeDom.Compiler.GeneratedCode(\"AutoFluentValidation\", \"" + Version + "\")]";

	private const string ExcludeFromCoverageAttribute = "[global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage]";

	private const string Header =
		"// <auto-generated/>\n" +
		"// Generated by AutoFluentValidation. Do not edit: add rules in your own partial class via ConfigureRules().\n" +
		"#nullable disable\n" +
		"#pragma warning disable CS1591, CS0612, CS0618\n" +
		"using global::FluentValidation;\n";

	public static string EmitValidator(ValidatorSpec spec) {
		var sb = new StringBuilder(Header).Append('\n');
		string indent = "";
		if (spec.Namespace is not null) {
			sb.Append("namespace ").Append(spec.Namespace).Append("\n{\n");
			indent = "    ";
		}

		var name = spec.ValidatorName;
		// No modifier: the class is internal by default, or takes the accessibility the user's half declares.
		var modifier = spec.IsPublic ? "public " : "";
		Line(sb, indent, "/// <summary>Generated FluentValidation validator for <see cref=\"" + spec.ModelFullName.Replace("global::", "").Replace('<', '{').Replace('>', '}') + "\"/>.</summary>");
		Line(sb, indent, GeneratedCodeAttribute);
		Line(sb, indent, ExcludeFromCoverageAttribute);
		Line(sb, indent, modifier + "partial class " + name + " : global::FluentValidation.AbstractValidator<" + spec.ModelFullName + ">");
		Line(sb, indent, "{");
		var body = indent + "    ";
		Line(sb, body, "private static readonly global::System.Lazy<" + name + "> s_shared = new global::System.Lazy<" + name + ">(() => new " + name + "());");
		sb.Append('\n');
		Line(sb, body, "/// <summary>A lazily created shared instance, used for nested validation. Validators are stateless and thread-safe.</summary>");
		Line(sb, body, "public static " + name + " Shared => s_shared.Value;");
		sb.Append('\n');
		Line(sb, body, "public " + name + "()");
		Line(sb, body, "{");
		var stmt = body + "    ";
		if (spec.StopOnFirstFailure)
			Line(sb, stmt, "RuleLevelCascadeMode = global::FluentValidation.CascadeMode.Stop;");
		foreach (var statement in spec.RuleStatements) {
			var lines = statement.Split('\n');
			Line(sb, stmt, lines[0]);
			for (int i = 1; i < lines.Length; i++) Line(sb, stmt + "    ", lines[i]);
		}
		Line(sb, stmt, "ConfigureRules();");
		Line(sb, body, "}");
		sb.Append('\n');
		Line(sb, body, "/// <summary>Implement in your own <c>partial class " + name + "</c> to add hand-written rules after the generated ones.</summary>");
		Line(sb, body, "partial void ConfigureRules();");
		Line(sb, indent, "}");
		if (spec.Namespace is not null) sb.Append("}\n");
		return sb.ToString();
	}

	public static string EmitRegistration(RegistrationSpec spec) {
		var sb = new StringBuilder(Header).Append('\n');
		sb.Append("namespace ").Append(spec.Namespace).Append("\n{\n");
		Line(sb, "    ", "/// <summary>Registers every validator generated by AutoFluentValidation in this assembly.</summary>");
		Line(sb, "    ", GeneratedCodeAttribute);
		Line(sb, "    ", ExcludeFromCoverageAttribute);
		Line(sb, "    ", "public static class AutoValidatorServiceCollectionExtensions");
		Line(sb, "    ", "{");
		const string Di = "global::Microsoft.Extensions.DependencyInjection.";
		Line(sb, "        ", "/// <summary>");
		Line(sb, "        ", "/// Registers each generated validator as <c>IValidator&lt;TModel&gt;</c> and as its concrete type.");
		Line(sb, "        ", "/// Registrations that already exist are kept, so calling this more than once is safe.");
		Line(sb, "        ", "/// Uses no reflection, so it is trimming- and Native-AOT-friendly.");
		Line(sb, "        ", "/// </summary>");
		Line(sb, "        ", "public static " + Di + "IServiceCollection AddAutoValidators(");
		Line(sb, "            ", "this " + Di + "IServiceCollection services,");
		Line(sb, "            ", Di + "ServiceLifetime lifetime = " + Di + "ServiceLifetime.Scoped)");
		Line(sb, "        ", "{");
		Line(sb, "            ", "if (services is null) throw new global::System.ArgumentNullException(nameof(services));");
		foreach (var entry in spec.Entries) {
			Line(sb, "            ", Di + "Extensions.ServiceCollectionDescriptorExtensions.TryAddEnumerable(services, new " + Di + "ServiceDescriptor(typeof(global::FluentValidation.IValidator<" + entry.ModelFullName + ">), typeof(" + entry.ValidatorFullName + "), lifetime));");
			Line(sb, "            ", Di + "Extensions.ServiceCollectionDescriptorExtensions.TryAdd(services, new " + Di + "ServiceDescriptor(typeof(" + entry.ValidatorFullName + "), typeof(" + entry.ValidatorFullName + "), lifetime));");
		}
		Line(sb, "            ", "return services;");
		Line(sb, "        ", "}");
		Line(sb, "    ", "}");
		sb.Append("}\n");
		return sb.ToString();
	}

	private static void Line(StringBuilder sb, string indent, string text) => sb.Append(indent).Append(text).Append('\n');
}
